changeSet.sql:
CREATE TABLE likes ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, profile_id BIGINT NOT NULL, likeable_type VARCHAR(20) NOT NULL CHECK (likeable_type IN ('post', 'comment', 'story')), likeable_id BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), deleted_at TIMESTAMPTZ,
CONSTRAINT LIKES_PROFILE_FK FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE );
CREATE UNIQUE INDEX idx_likes_unique_active ON likes(profile_id, likeable_type, likeable_id) WHERE deleted_at IS NULL;
CREATE INDEX idx_likes_profile ON likes(profile_id) WHERE deleted_at IS NULL;
CREATE INDEX idx_likes_content ON likes(likeable_type, likeable_id) WHERE deleted_at IS NULL;
